    START TRANSACTION;
    UPDATE students p JOIN users u ON u.email=p.email AND u.role='student'
        SET p.profile_completed_at=p.created_at
        WHERE p.profile_completed_at IS NULL AND TRIM(p.student_id)<>'' AND TRIM(p.full_name)<>''
          AND TRIM(p.email)<>'' AND p.email LIKE '%_@_%._%'
          AND u.username=p.student_id AND u.ref_id=p.student_id AND u.full_name=p.full_name
          AND (p.user_id IS NULL OR p.user_id=u.id)
          AND NOT EXISTS (SELECT 1 FROM students sibling WHERE sibling.id<>p.id AND sibling.user_id=u.id)
          AND NOT EXISTS (SELECT 1 FROM advisers o WHERE o.email=p.email OR o.user_id=u.id)
          AND NOT EXISTS (SELECT 1 FROM account_invitations i WHERE i.user_id=u.id);
    UPDATE advisers p JOIN users u ON u.email=p.email AND u.role='adviser'
        SET p.profile_completed_at=p.created_at
        WHERE p.profile_completed_at IS NULL AND TRIM(p.employee_id)<>'' AND TRIM(p.full_name)<>''
          AND TRIM(p.email)<>'' AND p.email LIKE '%_@_%._%'
          AND u.username=p.employee_id AND u.ref_id=p.employee_id AND u.full_name=p.full_name
